def upload_and_commit(block_svc, meta_svc, file_path: str, chunks: list[bytes], base_rev: int):
    hashes = [sha256(c) for c in chunks]
    missing = block_svc.negotiate(hashes)
    for h, c in zip(hashes, chunks):
        if h in missing:
            block_svc.put_chunk(h, c)
    return meta_svc.commit_manifest(file_path, hashes, base_rev)

def should_sync_file(sqlite_db, path: str, mtime: float, size: int) -> bool:
    if path.endswith(('.tmp', '.swp', '~')):
        return False
    row = sqlite_db.get_file(path)
    return row is None or row.mtime != mtime or row.size != size

def fetch_delta_since(conn, namespace_id: str, cursor: int, limit: int = 500) -> dict:
    rows = conn.execute(
        'SELECT seq_id, file_id, op_type, rev, chunks_json FROM namespace_journal '
        'WHERE namespace_id=%s AND seq_id > %s ORDER BY seq_id ASC LIMIT %s',
        (namespace_id, cursor, limit)
    )
    next_cursor = rows[-1]['seq_id'] if rows else cursor
    return {'entries': rows, 'cursor': next_cursor, 'has_more': len(rows) == limit}

def move_node_safe(conn, ns_id: str, node_id: str, new_parent_id: str) -> None:
    with conn.transaction():
        if is_descendant(conn, ns_id, candidate=new_parent_id, ancestor=node_id):
            raise ValueError('Cannot move folder into its own descendant')
        conn.execute('UPDATE nodes SET parent_id=%s WHERE namespace_id=%s AND id=%s', (new_parent_id, ns_id, node_id))

def fetch_chunk_prefer_lan(lan_peers, cdn_client, chunk_hash: str) -> bytes:
    for peer in lan_peers.lookup(chunk_hash):
        data = peer.try_fetch(chunk_hash, timeout=0.2)
        if data and sha256(data) == chunk_hash:
            return data
    return cdn_client.download_presigned(chunk_hash)

def rollback_namespace(conn, ns_id: str, target_ts: str) -> int:
    with conn.transaction():
        revs = conn.fetch_last_revisions_before(ns_id, target_ts)
        for file_id, rev in revs:
            conn.execute('UPDATE files SET head_rev=%s WHERE id=%s', (rev, file_id))
        return len(revs)
